-- Author: G3 database (Manas)
-- Description: fix availability_grid() from 0312.
--   * it raised "structure of query does not match function result type" on every call, because
--     status came back as text where the signature says VARCHAR(15)
--   * it called generate_train_consist_coaches() from a STABLE function, which wrote coaches
--     during a read; coaches are generated by db/import/generate_inventory.py instead
--   * the RAC limit was 8 here but 20 in G4's book_tickets(), so the grid said WL for
--     bookings that would really get RAC; both use 20 now
--   * the per-class seat counts were repeated eight times per row; they are worked out once
-- Same signature and result columns as 0312, so callers do not change.
CREATE OR REPLACE FUNCTION availability_grid(
    p_train_no TEXT,
    p_from_code TEXT,
    p_to_code TEXT,
    p_start_date DATE,
    p_days INT DEFAULT 6,
    p_quota TEXT DEFAULT 'GN'
)
RETURNS TABLE (
    travel_date DATE,
    class_code VARCHAR(5),
    class_name TEXT,
    status VARCHAR(15),
    available_count INT,
    rac_count INT,
    wl_count INT,
    fare NUMERIC(10,2)
)
LANGUAGE plpgsql
STABLE
AS $$
DECLARE
    v_train_id BIGINT;
    v_from_seq INT;
    v_to_seq INT;
    c_rac_capacity CONSTANT INT := 20;   -- keep equal to v_max_rac in book_tickets() (0408)
BEGIN
    SELECT t.train_id INTO v_train_id FROM trains t WHERE t.train_no = p_train_no;
    IF v_train_id IS NULL THEN
        RETURN;
    END IF;

    SELECT s.seq INTO v_from_seq
      FROM train_stops s JOIN stations st ON st.station_id = s.station_id
     WHERE s.train_id = v_train_id AND st.station_code = p_from_code;
    SELECT s.seq INTO v_to_seq
      FROM train_stops s JOIN stations st ON st.station_id = s.station_id
     WHERE s.train_id = v_train_id AND st.station_code = p_to_code;

    IF v_from_seq IS NULL OR v_to_seq IS NULL OR v_from_seq >= v_to_seq THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH dates AS (
        SELECT (p_start_date + i)::DATE AS dt FROM generate_series(0, p_days - 1) AS i
    ),
    class_berths AS (                      -- berths per class on this train
        SELECT c.class_code, tc.name AS class_name, count(b.berth_id)::INT AS total
          FROM coaches c
          JOIN travel_classes tc ON tc.class_code = c.class_code
          JOIN berths b ON b.coach_id = c.coach_id
         WHERE c.train_id = v_train_id
         GROUP BY c.class_code, tc.name
    ),
    counted AS (                           -- berths already sold on this stretch, per date and class
        SELECT d.dt, cb.class_code, cb.class_name, cb.total,
               (SELECT count(DISTINCT ba.berth_id)::INT
                  FROM berth_allocations ba
                  JOIN berths b ON b.berth_id = ba.berth_id
                  JOIN coaches c ON c.coach_id = b.coach_id
                 WHERE c.train_id = v_train_id AND c.class_code = cb.class_code
                   AND ba.run_date = d.dt
                   AND ba.stops && int4range(v_from_seq, v_to_seq, '[)')) AS sold
          FROM dates d CROSS JOIN class_berths cb
    )
    SELECT n.dt,
           n.class_code::VARCHAR(5),
           n.class_name,
           (CASE WHEN n.total - n.sold > 0 THEN 'AVAILABLE'
                 WHEN n.sold - n.total < c_rac_capacity THEN 'RAC'
                 ELSE 'WL' END)::VARCHAR(15),
           GREATEST(0, n.total - n.sold),
           -- the RAC place the next booking would get, counted from 1
           CASE WHEN n.total - n.sold <= 0 AND n.sold - n.total < c_rac_capacity
                THEN n.sold - n.total + 1 ELSE 0 END,
           -- the waiting-list number the next booking would get
           CASE WHEN n.sold - n.total >= c_rac_capacity
                THEN n.sold - n.total - c_rac_capacity + 1 ELSE 0 END,
           COALESCE((SELECT cf.total FROM calculate_fare(v_train_id, v_from_seq, v_to_seq, n.class_code, p_quota) cf), 0.00)
      FROM counted n
     ORDER BY n.dt, n.class_code;
END;
$$;
